#open file in fasta format, turn into a sequence hash
def fasta_to_hash(infile)
  f=File.open(infile,"r")
  return_hash = {}
  name = ""
  while line = f.gets do
    if line =~ /^\>/
      name = line.chomp
      return_hash[name] = ""
    else
      return_hash[name] += line.chomp
    end
  end
  f.close
  return return_hash
end

#sequence locator:
#align with HXB2, return location, percentage of similarity
def sequence_locator(seq="",temp_dir=File.dirname($0))
  hxb2_ref = ""
  hxb2_l = hxb2_ref.size
  head = ""
  8.times {head  << (65 + rand(25)).chr}
  temp_file = temp_dir + "/" + head + "_temp"
  temp_aln = temp_dir + "/" + head + "_temp_aln"
  
  l1 = 0
  l2 = 0
  name = ">test"
  temp_in = File.open(temp_file,"w")
  temp_in.puts ">ref"
  temp_in.puts hxb2_ref
  temp_in.puts name
  temp_in.puts seq
  temp_in.close
  
  print `muscle -in #{temp_file} -out #{temp_aln} -quiet`
  aln_seq = fasta_to_hash(temp_aln)
  aln_test = aln_seq[name]
  aln_test =~ /^(\-*)(\w.*\w)(\-*)$/
  gap_begin = $1.size
  gap_end = $3.size
  aln_test2 = $2
  ref = aln_seq[">ref"]
  ref = ref[gap_begin..(-gap_end-1)]
  ref_size = ref.size
  if ref_size > 1.3*(seq.size)
    l1 = l1 + gap_begin
    l2 = l2 + gap_end
    max_seq = aln_test2.scan(/[ACGT]+/).max_by(&:length)
    aln_test2 =~ /#{max_seq}/
    before_aln_seq = $`
    before_aln = $`.size
    post_aln_seq = $'
    post_aln = $'.size
    before_aln_seq_size = before_aln_seq.scan(/[ACGT]+/).join("").size
    b1 = (1.3 * before_aln_seq_size).to_i
    post_aln_seq_size = post_aln_seq.scan(/[ACGT]+/).join("").size
    b2 = (1.3 * post_aln_seq_size).to_i
    if (before_aln > seq.size) and (post_aln <= seq.size)
      ref = ref[(before_aln - b1)..(ref_size - post_aln - 1)]
      l1 = l1 + (before_aln - b1)
    elsif (post_aln > seq.size) and (before_aln <= seq.size)
      ref = ref[before_aln..(ref_size - post_aln - 1 + b2)]
      l2 = l2 + post_aln - b2
    elsif (post_aln > seq.size) and (before_aln > seq.size)
      ref = ref[(before_aln - b1)..(ref_size - post_aln - 1 + b2)]
      l1 = l1 + (before_aln - b1)
      l2 = l2 + (post_aln - b2)
    end
    temp_in = File.open(temp_file,"w")
    temp_in.puts ">ref"
    temp_in.puts ref
    temp_in.puts name
    temp_in.puts seq
    temp_in.close
    print `muscle -in #{temp_file} -out #{temp_aln} -quiet`
    aln_seq = fasta_to_hash(temp_aln)
    aln_test = aln_seq[name]
    aln_test =~ /^(\-*)(\w.*\w)(\-*)$/
    gap_begin = $1.size
    gap_end = $3.size
    aln_test2 = $2
    ref = aln_seq[">ref"]
    ref = ref[gap_begin..(-gap_end-1)]
    ref_size = ref.size
  end
  aln_seq = fasta_to_hash(temp_aln)
  aln_test = aln_seq[name]
  aln_test =~ /^(\-*)(\w.*\w)(\-*)$/
  gap_begin = $1.size
  gap_end = $3.size
  aln_test = $2
  aln_test =~ /^(\w+)(\-*)\w/
  s1 = $1.size
  g1 = $2.size
  aln_test =~ /\w(\-*)(\w+)$/
  s2 = $2.size
  g2 = $1.size
  ref = aln_seq[">ref"]
  ref = ref[gap_begin..(-gap_end-1)]

  l1 = l1 + gap_begin
  l2 = l2 + gap_end
  repeat = 0
  
  if g1 == g2 and (s1 + g1 + s2) == ref.size
    if s1 > s2 and g2 > 2*s2
      ref = ref[0..(-g2-1)]
      repeat = 1
      l2 = l2 + g2
    elsif s1 < s2 and g1 > 2*s1
      ref = ref[g1..-1]
      repeat = 1
      l1 = l1 + g1
    end
  else
    if g1 > 2*s1
      ref = ref[g1..-1]
      repeat = 1
      l1 = l1 + g1
    end
    if g2 > 2*s2
      ref = ref[0..(-g2 - 1)]
      repeat = 1
      l2 = l2 + g2
    end 
  end

  while repeat == 1
    temp_in = File.open(temp_file,"w")
    temp_in.puts ">ref"
    temp_in.puts ref
    temp_in.puts name
    temp_in.puts seq
    temp_in.close
    print `muscle -in #{temp_file} -out #{temp_aln} -quiet`
    aln_seq = fasta_to_hash(temp_aln)
    aln_test = aln_seq[name]
    aln_test =~ /^(\-*)(\w.*\w)(\-*)$/
    gap_begin = $1.size
    gap_end = $3.size
    aln_test = $2
    aln_test =~ /^(\w+)(\-*)\w/
    s1 = $1.size
    g1 = $2.size
    aln_test =~ /\w(\-*)(\w+)$/
    s2 = $2.size
    g2 = $1.size
    ref = aln_seq[">ref"]
    ref = ref[gap_begin..(-gap_end-1)]
    l1 = l1 + gap_begin
    l2 = l2 + gap_end
    repeat = 0
    if g1 > 2*s1
      ref = ref[g1..-1]
      repeat = 1
      l1 = l1 + g1
    end
    if g2 > 2*s2
      ref = ref[0..(-g2 - 1)]
      repeat = 1
      l2 = l2 + g2
    end
  end
  ref = hxb2_ref[l1..(hxb2_l - l2 - 1)]
  
  temp_in = File.open(temp_file,"w")
  temp_in.puts ">ref"
  temp_in.puts ref
  temp_in.puts name
  temp_in.puts seq
  temp_in.close
  print `muscle -in #{temp_file} -out #{temp_aln} -quiet`
  aln_seq = fasta_to_hash(temp_aln)
  aln_test = aln_seq[name]
  ref = aln_seq[">ref"]

  ref_size = ref.size
  sim_count = 0
  (0..(ref_size-1)).each do |n|
    ref_base = ref[n]
    test_base = aln_test[n]
    sim_count += 1 if ref_base == test_base
  end
  similarity = (sim_count/ref_size.to_f*100).round(1)
  print `rm -f #{temp_file}`
  print `rm -f #{temp_aln}`
  loc_p1 = l1 + 1
  loc_p2 = hxb2_l - l2
  if seq.size != (loc_p2 - loc_p1 + 1)
      indel = true
  elsif aln_test.include?("-")
      indel = true
  end
  return [loc_p1,loc_p2,similarity,indel,aln_test,ref]
end

#gene cutter. given a specific HXB2 position array [first_position,last_position], return a sequence within the range
#return nil if seqeuence not in the range.
#require sequence_locator.
def sequence_clip(loc={},positions=[])
    p1 = positions[0]
    p2 = positions[1]
    l1 = loc[0]
    l2 = loc[1]
    if (p1 >= l1) & (p2 <= l2)
        seq = loc[4]
        ref = loc[5]
        g1 = 0
        ref.each_char do |char|
            break if l1 == p1
            g1 += 1
            l1 += 1 unless char == "-"
        end
        g2 = 1
        ref.reverse.each_char do |char|
            break if l2 == p2
            g2 += 1
            l2 -= 1 unless char == "-"
        end
        return seq[g1..(-g2)].tr("-","")
    else
        return nil
    end
end


#regions to be cut
regions = {"VIF"=>[5489, 5961], "V1V3"=>[6585, 7208], "NEFa"=>[8931, 9341], "ENV2"=>[6585, 6989], "ENV4"=>[7219, 7655]}

# "VIF"=>[5489, 5961]
# "V1V3"=>[6585, 7208]
# "NEFa"=>[8931, 9341]
# "ENV2"=>[6585, 6989]
# "ENV4"=>[7219, 7655]

indir = ARGV[0]

files = []
Dir.chdir(indir) {files = Dir.glob("*")}
out_files = {}
files.each do |f|
    infile = indir + "/" + f
    seqs = fasta_to_hash(infile)
    seq_loc = {}
    seqs.each do |k,v|
        loc = sequence_locator(v)
        seq_loc[k] = loc
    end
 
    out_seq_hash = {}
    regions.each do |region,positions|
        out_seq_hash[region] = {}
        seq_loc.each do |name,loc|
            clipped_seq = sequence_clip(loc,positions)
            if clipped_seq
                out_name = name + "_" + region
                out_seq_hash[region][out_name] = clipped_seq
            end
        end
    end
    out_files[f] = out_seq_hash 
end
outdir = indir + "_5regions"
Dir.mkdir(outdir) unless File.directory?(outdir)

regions.keys.each do |region|
    region_dir = outdir + "/" + region
    Dir.mkdir(region_dir) unless File.directory?(region_dir)
    
    out_files.each do |k,v|
        outfile = region_dir + "/" + File.basename(k,".*") + "_" + region + ".fas"
        out = File.open(outfile,"w")
        seqs = v[region]
        next unless seqs
        seqs.each do |n,s|
            out.puts n
            out.puts s
        end
    end
end